class Topic<T> {
  readonly #subscribers = new Set<(value: T) => Promise<void>>();

  subscribe(fn: (value: T) => Promise<void>): () => void {
    this.#subscribers.add(fn);
    return () => {
      this.#subscribers.delete(fn);
    };
  }

  async publish(value: T): Promise<number> {
    const results = await Promise.allSettled([...this.#subscribers].map((fn) => fn(value)));
    return results.filter((r) => r.status === "rejected").length;
  }
}

const topic = new Topic<string>();
const done: string[] = [];
topic.subscribe(async (id) => void done.push(`email ${id}`));
const stop = topic.subscribe(async () => {
  throw new Error("analytics down");
});
topic.subscribe(async (id) => void done.push(`ship ${id}`));

console.log(await topic.publish("ORD-1"), done);
stop();
console.log(await topic.publish("ORD-2"));

