type Command = { execute(): void; undo(): void };
const stock = new Map<string, number>([["RICE-5KG", 10]]);

function changeStock(levels: Map<string, number>, sku: string, qty: number): Command {
  let previous: number | undefined;
  return {
    execute() {
      previous = levels.get(sku) ?? 0;
      levels.set(sku, qty);
    },
    undo() {
      if (previous === undefined) throw new Error("never executed");
      levels.set(sku, previous);
    },
  };
}

const fix = changeStock(stock, "RICE-5KG", 3);
