type Command = { description: string; execute(): void; undo(): void };

let price = 1;
const double: Command = { description: "double price", execute: () => void (price *= 2), undo: () => void (price /= 2) };

class History {
  readonly #done: Command[] = [];
  readonly audit: string[] = [];

  run(command: Command, user: string): void {
    command.execute();
    this.#done.push(command);
    this.audit.push(`${user}: ${command.description}`);
  }

  undo(user: string): boolean {
    const command = this.#done.pop();
    if (command === undefined) return false;
    command.undo();
    this.audit.push(`${user}: undo ${command.description}`);
    return true;
  }
}

const history = new History();
history.run(double, "musa");
history.undo("ngozi");
console.log(price);
console.log(history.undo("ngozi"));
console.log(history.audit);
// expected audit: [ 'musa: double price', 'ngozi: undo double price' ]

