type JobCommand = { type: "SendReceipt"; orderId: string };

function parseJob(text: string): JobCommand | undefined {
  const data: unknown = JSON.parse(text);
  if (typeof data !== "object" || data === null) return undefined;
  if (!("type" in data) || data.type !== "SendReceipt") return undefined;
  if (!("orderId" in data) || typeof data.orderId !== "string") return undefined;
  return { type: "SendReceipt", orderId: data.orderId };
}

const ok = parseJob('{"type":"SendReceipt","orderId":"ORD-9"}');
console.log(ok?.type, ok?.orderId);
console.log(parseJob('{"type":"SendReceipt","orderId":9}'));
console.log(parseJob('{"type":"DropTables"}'));

