type Mw = (ctx: string[], next: () => Promise<string>) => Promise<string>;

const logMw: Mw = async (ctx, next) => {
  ctx.push("log in");
  const result = await next();
  ctx.push("log out");
  return result;
};
const authMw: Mw = async (ctx, next) => {
  ctx.push("auth ok");
  return next();
};

function chain(middlewares: Mw[], handler: (ctx: string[]) => Promise<string>) {
  return (ctx: string[]): Promise<string> => {
    const run = (i: number): Promise<string> => {
      const middleware = middlewares[i];
      return middleware === undefined ? handler(ctx) : middleware(ctx, () => run(i + 1));
    };
    return run(0);
  };
}

const trace: string[] = [];
await chain([logMw, authMw], async (ctx) => {
  ctx.push("handler");
  return "done";
})(trace);
console.log(trace);

