type Ctx = { user?: { role: string } };
type Res = { status: number };
type Mw = (ctx: Ctx, next: () => Promise<Res>) => Promise<Res>;

function requireRole(role: string): Mw {
  return async (ctx, next) => (ctx.user?.role === role ? next() : { status: 403 });
}

const handler = async (): Promise<Res> => ({ status: 200 });
const guard = requireRole("admin");
const a = await guard({ user: { role: "support" } }, handler);
const b = await guard({ user: { role: "admin" } }, handler);
console.log(a.status, b.status);

type Approve = (kobo: number) => string;

function approver(name: string, limitKobo: number, next?: Approve): Approve {
  return (kobo) => {
    if (kobo <= limitKobo) return name;
    return next === undefined ? "nobody" : next(kobo);
  };
}

const chain = approver("support", 500000, approver("manager", 10000000, approver("finance", 100000000)));
